    aDirDeltaTable[9] = -1;
    aDirDeltaTable[0xc] = -1;
    aDirDeltaTable[0xf] = -1;
    aDirDeltaTable[0x12] = -1;
    aDirDeltaTable[0x15] = -1;
    aDirDeltaTable[0x18] = -1;
