    aDirDeltaTable[0xd] = 0;
    aDirDeltaTable[0x10] = 0;
    aDirDeltaTable[0x13] = 0;
    aDirDeltaTable[0x16] = 0;
    aDirDeltaTable[0x19] = 0;
    aDirDeltaTable[0x1c] = 0;
