    aDirDeltaTable[5] = 1;
    aDirDeltaTable[8] = 1;
    aDirDeltaTable[0xb] = 1;
    aDirDeltaTable[0xe] = 1;
    aDirDeltaTable[0x11] = 1;
    aDirDeltaTable[0x14] = 1;
    aDirDeltaTable[0x17] = 1;
    aDirDeltaTable[0x1a] = 1;
    aDirDeltaTable[0x1d] = 1;
    aDirDeltaTable[0x1f] = 1;
