    nPackedPrev.nY = pPathTypeArgs->pCoords.nPosX;
    D2DynamicPathStrc* pDynamicPath = pPathTypeArgs->pDynamicPath;
    D2RoomStrc* pRoom = pDynamicPath->pRoom;
